-- rowstile 0.1.0-dev: sync_spread_from_tops. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '3823b78b0065f497', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '3823b78b0065f497' THEN
    PERFORM pg_catalog.set_config('authz_migration.read_only', pg_catalog.current_setting('default_transaction_read_only'), false);
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '3823b78b0065f497' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only until the migration''s last statement; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '3823b78b0065f497' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '497364bae5b1be84' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '497364bae5b1be84', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'conf_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('folder__parent__tree', ARRAY[to_regclass('"app"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"app"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."folder__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

-- What the app role evaluates itself (its rules, the views they read, the rules' own functions, the masked views)
-- calls nothing of the app's that may read data: a call the condition's text doesn't show isn't run as the owner
DO $ac$
DECLARE r record;
BEGIN
  FOR r IN
    WITH RECURSIVE read(classid, objid, what) AS (
      SELECT x.classid, x.objid, x.what FROM (
        SELECT 'pg_policy'::regclass::oid AS classid, p.oid AS objid,
               format('the %s rule of %s', substr(p.polname::text, 7), p.polrelid::regclass) AS what
        FROM pg_policy p JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
         AND d.description IN ('rowstile')
        UNION ALL
        SELECT 'pg_proc'::regclass::oid, f.oid, 'the rules of ' || split_part(f.proname::text, ':', 1)
        FROM pg_proc f WHERE f.pronamespace = 'authz_gen'::regnamespace
        UNION ALL
        SELECT 'pg_rewrite'::regclass::oid, w.oid, 'the masked view ' || c.oid::regclass
        FROM pg_class c JOIN pg_description d ON d.objoid = c.oid AND d.classoid = 'pg_class'::regclass
         AND d.description IN ('rowstile masked view')
        JOIN pg_rewrite w ON w.ev_class = c.oid) x
      UNION
      -- (the views they read, and those these read: a view runs what it calls as whoever reads it)
      SELECT 'pg_rewrite'::regclass::oid, w.oid, rd.what
      FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
       AND dep.refclassid = 'pg_class'::regclass
      JOIN pg_class v ON v.oid = dep.refobjid AND v.relkind = 'v' AND v.relnamespace = 'authz_int'::regnamespace
      JOIN pg_rewrite w ON w.ev_class = v.oid)
    SELECT rd.what, fn.oid::regprocedure::text AS fn
    FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
    JOIN pg_proc fn ON fn.oid = CASE dep.refclassid
        WHEN 'pg_proc'::regclass THEN dep.refobjid
        WHEN 'pg_operator'::regclass THEN (SELECT o.oprcode FROM pg_operator o WHERE o.oid = dep.refobjid) END
    WHERE fn.pronamespace NOT IN (SELECT n.oid FROM pg_namespace n
                                  WHERE n.nspname IN ('pg_catalog', 'authz', 'authz_gen', 'authz_int'))
      AND fn.provolatile <> 'i'
      AND fn.prolang NOT IN (SELECT l.oid FROM pg_language l WHERE l.lanname IN ('internal', 'c'))
    ORDER BY 1, 2 LIMIT 1
  LOOP
    RAISE EXCEPTION '%: a condition calls %, and nothing in its text shows the call (a function of the row read as a column, a cast, an operator written OPERATOR(...)), so the app role would run it with its own rights, not the policy''s [AZ628]', r.what, r.fn
      USING HINT = 'call it by its name, with parentheses, on the row''s columns, as {app.blocked_doc(this.id)}: rowstile then runs it with the policy''s rights. A function that reads nothing may be marked IMMUTABLE instead';
  END LOOP;
END $ac$;

-- what reads the objects a transaction changed, and what reads those, to the end (no limit: each is worked out again)
CREATE OR REPLACE FUNCTION authz_int.sync_spread(p_tx bigint, p_round int) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE v_r int := p_round; n bigint;
BEGIN
  LOOP
    INSERT INTO authz_int.sync_todo (txid, type, id, round)
    SELECT DISTINCT $1, d.t, d.i, authz__.v_r + 1 FROM (
      SELECT 'file'::text AS t, v.id::text AS i FROM (SELECT x."id"::text FROM "app"."files" x WHERE x."folder_id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'folder' AND x.round = authz__.v_r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))))) v(id)
      UNION ALL SELECT 'file'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'folder' AND x.round = authz__.v_r AND x.id = '*')
      UNION ALL SELECT 'folder'::text AS t, v.id::text AS i FROM (WITH d AS MATERIALIZED (SELECT DISTINCT u._x FROM unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'folder' AND x.round = authz__.v_r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS u(_x) WHERE u._x IS NOT NULL)
  SELECT c.descendant::text FROM authz_int."folder__parent__tree" c WHERE c.ancestor IN (
    SELECT d._x FROM d WHERE NOT EXISTS (
      SELECT 1 FROM ((SELECT x._parent FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "app"."folders" r WHERE r."parent_id" IS NOT NULL AND r."id" = d._x) x OFFSET 0)) e JOIN d p ON p._x = e._parent
      WHERE e._parent <> d._x
        AND EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" a WHERE a.descendant = d._x AND a.ancestor = e._parent OFFSET 0)))) v(id)
      UNION ALL SELECT 'folder'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'folder' AND x.round = authz__.v_r AND x.id = '*')
      UNION ALL SELECT 'note'::text AS t, v.id::text AS i FROM (SELECT x."id"::text FROM "app"."notes" x WHERE x."file_id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'file' AND x.round = authz__.v_r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))))) v(id)
      UNION ALL SELECT 'note'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'file' AND x.round = authz__.v_r AND x.id = '*')) d WHERE d.i IS NOT NULL
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0 AND NOT EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = p_tx AND x.round > authz__.v_r);
    v_r := v_r + 1;
  END LOOP;
  RETURN v_r;
END $f$;

-- The index made current for the objects a transaction changed and what reads them (the difference written, not
-- every row again): at its commit, in it, or after it, by the worker. The groups first, then the keys (a principal
-- holds the keys of every group whose members hold one of its own, through groups inside groups), then the readers
-- (JIT off: its statements read a few rows each, through indexes, which a plan made for many would compile for; no
-- merge joins: its sets of keys, which the planner can't count, are joined by hash, not sorted as text)
CREATE OR REPLACE FUNCTION authz_int.sync_process() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET jit = off SET enable_mergejoin = off AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE
  v_tx bigint := txid_current();
  v_round int;
  v_mode int[]; v_w int[]; v_r int[]; v_s int; v_x boolean; v_hi int; v_nowait boolean := false;
  v_ids text[]; v_part text[]; v_from int; v_now text[];
  v_keys text[] := '{}';     -- the keys a principal gained or lost
  v_came text[] := '{}';     -- the principals who are somebody now, and held no key (type:id)
  v_whole text[] := '{}';    -- the principal types worked out whole
  v_keys_locked boolean := false;
  v_all boolean;               -- every principal's keys worked out whole (applying): the groups' changes aren't followed
  v_n bigint;
  v_found int;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx) THEN RETURN; END IF;
  IF current_setting('transaction_isolation') IN ('repeatable read', 'serializable') THEN
    -- a snapshot older than another's index write: a serialization error, rather than readers worked out from
    -- what it can't see
    PERFORM 1 FROM authz_int.sync_stripes s ORDER BY s.stripe FOR UPDATE;
    UPDATE authz_int.sync_stripes SET n = n;
    v_round := authz_int.sync_spread(v_tx, 0);
  ELSE
    -- READ COMMITTED: the lock rows of what the work writes (what changed, and what reads it), and, shared, of what
    -- it reads (the folders above, what they link to), in one order. A writer whose work meets this one's waits for
    -- it, then sees what it committed; once they are held, what reads the changes is looked for again, and the lock
    -- rows of anything new are taken too, until there is none. A later pass may need a lock row below one it holds
    -- (or one it holds shared, now to write): taken out of order, two writers could wait on each other, so it takes
    -- those only if nobody holds them (NOWAIT); when one is held, it lets go of every lock row it took (the block's
    -- subtransaction rolled back) and takes them all again, in order
    LOOP
      BEGIN
        v_mode := array_fill(0, ARRAY[4096]);
        v_hi := -1;
        LOOP
          v_round := authz_int.sync_spread(v_tx, 0);
          IF EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id = '*') THEN
            v_w := ARRAY(SELECT generate_series(0, 4095));
            v_r := '{}';
          ELSE
            v_w := ARRAY(SELECT DISTINCT pg_catalog.hashtext(x.type || ':' || x.id) & 4095
                         FROM authz_int.sync_todo x WHERE x.txid = v_tx);
            v_r := ARRAY(SELECT DISTINCT pg_catalog.hashtext(d.k) & 4095 FROM (
                            SELECT 'folder:' || v.id FROM (SELECT (x."folder_id")::text FROM "app"."files" x WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'file' AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS id)) v(id)
                        UNION SELECT 'folder:' || v.id FROM (WITH d AS MATERIALIZED (SELECT DISTINCT u._x FROM unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'folder' AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS u(_x) WHERE u._x IS NOT NULL),
  up AS MATERIALIZED (SELECT DISTINCT e._parent AS _p FROM d CROSS JOIN LATERAL ((SELECT x._parent FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "app"."folders" r WHERE r."parent_id" IS NOT NULL AND r."id" = d._x) x OFFSET 0)) e
                      WHERE e._parent IS NOT NULL AND NOT EXISTS (SELECT 1 FROM d o WHERE o._x = e._parent))
  SELECT d._x::text FROM d
  UNION SELECT u._p::text FROM up u
  UNION SELECT c.ancestor::text FROM authz_int."folder__parent__tree" c WHERE c.descendant IN (SELECT u._p FROM up u)) v(id)
                        UNION SELECT 'file:' || v.id FROM (SELECT (x."file_id")::text FROM "app"."notes" x WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'note' AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS id)) v(id)) d(k) WHERE d.k IS NOT NULL);
          END IF;
          v_n := 0;
          FOR v_s, v_x IN SELECT z.s, bool_or(z.x) FROM (SELECT unnest(v_w) AS s, true AS x UNION ALL SELECT unnest(v_r), false) z
                          GROUP BY z.s ORDER BY z.s LOOP
            CONTINUE WHEN v_mode[v_s + 1] = 2 OR (NOT v_x AND v_mode[v_s + 1] = 1);
            v_nowait := v_s <= v_hi;
            IF v_nowait THEN
              IF v_x THEN
                PERFORM 1 FROM authz_int.sync_stripes WHERE stripe = v_s FOR UPDATE NOWAIT;
              ELSE
                PERFORM 1 FROM authz_int.sync_stripes WHERE stripe = v_s FOR SHARE NOWAIT;
              END IF;
              v_nowait := false;
            END IF;
            IF v_x THEN
              UPDATE authz_int.sync_stripes SET n = n WHERE stripe = v_s;
              v_mode[v_s + 1] := 2;
            ELSE
              PERFORM 1 FROM authz_int.sync_stripes WHERE stripe = v_s FOR SHARE;
              v_mode[v_s + 1] := 1;
            END IF;
            v_hi := greatest(v_hi, v_s);
            v_n := v_n + 1;
          END LOOP;
          EXIT WHEN v_n = 0;
        END LOOP;
        EXIT;
      EXCEPTION WHEN lock_not_available THEN
        -- (a wait the session's lock_timeout ended is the caller's error)
        IF NOT v_nowait THEN
          RAISE;
        END IF;
        v_nowait := false;
      END;
    END LOOP;
  END IF;
  v_all := (SELECT count(DISTINCT x.type) FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id = '*'
            AND x.type = ANY (ARRAY['user']::text[])) = 1;
  -- team's groups
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'team' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "app"."teams" x UNION SELECT x."team_id"::text FROM "app"."team_members" x UNION SELECT x."parent_id"::text FROM "app"."teams" x UNION SELECT g.object_id FROM authz.shares g WHERE g.object_type = 'team' UNION SELECT substr(g.grp, strpos(g.grp, ':') + 1) FROM authz_sync.groups g WHERE left(g.grp, strpos(g.grp, ':')) = ANY (ARRAY['team#member:']::text[])) ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'team') END;
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
      WITH fresh AS MATERIALIZED (SELECT 'team#member:' || f.o_id::text AS grp, f.o_key AS key FROM authz_int."sync:team.member"(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f WHERE NOT f.o_dep),
      gone AS (DELETE FROM authz_sync.groups g WHERE g.grp IN (SELECT 'team#member:' || v FROM unnest(v_part) v)
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.grp = g.grp AND f.key = g.key) RETURNING g.grp, g.key),
      made AS (INSERT INTO authz_sync.groups SELECT f.grp, f.key FROM fresh f ON CONFLICT DO NOTHING RETURNING grp, key)
      INSERT INTO authz_int.sync_moved SELECT v_tx, z.grp, z.key, z.made
      FROM (SELECT grp, key, false AS made FROM gone UNION ALL SELECT grp, key, true FROM made) z
      WHERE NOT v_all;
  END LOOP;
  -- the keys, where the groups' rows or the principals changed: under one lock row, taken last (nothing after it waits
  -- for another lock)
  IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx)
     OR EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = ANY (ARRAY['user']::text[])) THEN
    IF NOT v_keys_locked THEN
      UPDATE authz_int.locks SET n = n + 1 WHERE type = 'sync#keys';
    END IF;
    -- the principals of user: every one worked out whole (applying), or those that changed: one who is
    -- nobody now (gone, or failing the type's where) holds no key, and one who is somebody now and held none gets theirs
    IF EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'user' AND x.id = '*') THEN
      v_whole := v_whole || 'user'::text;
      v_ids := ARRAY(SELECT x."id"::text FROM "app"."users" x UNION SELECT k.principal_id FROM authz_sync.keys k WHERE k.principal_type = 'user');
      WITH fresh AS MATERIALIZED (SELECT * FROM authz_int."sync_keys:user"(v_ids)),
      gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id IN (SELECT unnest(v_ids))
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_id = k.principal_id AND f.o_key = k.key) RETURNING k.key),
      made AS (INSERT INTO authz_sync.keys SELECT 'user', f.o_id, f.o_key FROM fresh f ON CONFLICT DO NOTHING RETURNING key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.k), '{}') INTO v_keys FROM (SELECT key FROM gone UNION SELECT key FROM made) z(k);
    ELSE
      v_ids := ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'user');
      IF cardinality(v_ids) > 0 THEN
        v_now := ARRAY(SELECT x."id"::text FROM "app"."users" x WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(authz__.v_ids) v WHERE pg_catalog.pg_input_is_valid(v, 'integer')))));
        WITH gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id = ANY (v_ids)
                      AND k.principal_id <> ALL (v_now) RETURNING k.key)
        SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM gone z;
        v_came := v_came || ARRAY(SELECT 'user' || ':' || v FROM unnest(v_now) v WHERE NOT EXISTS (
          SELECT 1 FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id = v));
      END IF;
    END IF;
    -- a group's row gone: the keys above it that its member's holders held may go, unless what is left gives them
    -- again (each found given is taken back from those that may go, as often as it finds more)
    IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx AND NOT m.made) THEN
      WITH RECURSIVE up(src, c) AS (
        SELECT DISTINCT m.key, m.grp FROM authz_int.sync_moved m WHERE m.txid = v_tx AND NOT m.made
        UNION
        SELECT up.src, g.grp FROM up JOIN authz_sync.groups g ON g.key = up.c)
      -- (the holders of each key, a lookup by the keys' index: OFFSET 0 keeps the planner from reading every key for a
      -- few; then the sets joined whole)
      , by_src AS MATERIALIZED (
        SELECT DISTINCT up.c, k.principal_type AS pt, k.principal_id AS pid FROM up
        CROSS JOIN LATERAL (SELECT k.principal_type, k.principal_id FROM authz_sync.keys k WHERE k.key = up.src
                            AND k.principal_type <> ALL (v_whole) OFFSET 0) k),
      by_c AS MATERIALIZED (
        SELECT c.c, h.principal_type AS pt, h.principal_id AS pid FROM (SELECT DISTINCT up.c FROM up) c
        CROSS JOIN LATERAL (SELECT h.principal_type, h.principal_id FROM authz_sync.keys h WHERE h.key = c.c OFFSET 0) h)
      INSERT INTO authz_int.sync_lost (txid, ptype, pid, key)
      SELECT v_tx, s.pt, s.pid, s.c FROM by_src s JOIN by_c h ON h.c = s.c AND h.pt = s.pt AND h.pid = s.pid
      ON CONFLICT DO NOTHING;
      -- given again: by a member it holds that may not go (the holders of the members of the groups that may go, once
      -- each); then, round by round, by a member just found given
      WITH members AS MATERIALIZED (
        SELECT g.grp, g.key FROM (SELECT DISTINCT l.key FROM authz_int.sync_lost l WHERE l.txid = v_tx) c
        CROSS JOIN LATERAL (SELECT g.grp, g.key FROM authz_sync.groups g WHERE g.grp = c.key OFFSET 0) g),
      held AS MATERIALIZED (
        SELECT m.key, h.principal_type AS pt, h.principal_id AS pid FROM (SELECT DISTINCT key FROM members) m
        CROSS JOIN LATERAL (SELECT h.principal_type, h.principal_id FROM authz_sync.keys h WHERE h.key = m.key OFFSET 0) h),
      -- (the groups each holder holds a member of, that may not go; then the candidates they give again)
      supported AS MATERIALIZED (
        SELECT DISTINCT g.grp, h.pt, h.pid FROM members g JOIN held h ON h.key = g.key
        WHERE NOT EXISTS (SELECT 1 FROM authz_int.sync_lost o WHERE o.txid = v_tx AND o.ptype = h.pt AND o.pid = h.pid
                          AND o.key = h.key)),
      given AS (SELECT l.ptype, l.pid, l.key FROM authz_int.sync_lost l
                JOIN supported s ON s.grp = l.key AND s.pt = l.ptype AND s.pid = l.pid WHERE l.txid = v_tx),
      r AS (DELETE FROM authz_int.sync_lost l USING given z WHERE l.txid = v_tx AND l.ptype = z.ptype AND l.pid = z.pid
            AND l.key = z.key RETURNING l.ptype, l.pid, l.key)
      INSERT INTO authz_int.sync_found SELECT v_tx, r.ptype, r.pid, r.key, 1 FROM r;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_found := 1;
      WHILE v_n > 0 LOOP
        WITH r AS (DELETE FROM authz_int.sync_lost l
                   USING (SELECT DISTINCT f.ptype, f.pid, g.grp FROM authz_int.sync_found f
                          JOIN authz_sync.groups g ON g.key = f.key WHERE f.txid = v_tx AND f.round = v_found) z
                   WHERE l.txid = v_tx AND l.ptype = z.ptype AND l.pid = z.pid AND l.key = z.grp
                   RETURNING l.ptype, l.pid, l.key)
        INSERT INTO authz_int.sync_found SELECT v_tx, r.ptype, r.pid, r.key, v_found + 1 FROM r;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        v_found := v_found + 1;
      END LOOP;
      DELETE FROM authz_int.sync_found f WHERE f.txid = v_tx;
      WITH gone AS (DELETE FROM authz_sync.keys k USING authz_int.sync_lost l WHERE l.txid = v_tx
                    AND k.principal_type = l.ptype AND k.principal_id = l.pid AND k.key = l.key RETURNING k.key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM gone z;
      DELETE FROM authz_int.sync_lost l WHERE l.txid = v_tx;
    END IF;
    -- a group's row made: its member's holders hold the group, and the groups above it
    IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx AND m.made) THEN
      WITH RECURSIVE up(src, c) AS (
        SELECT DISTINCT m.key, m.grp FROM authz_int.sync_moved m WHERE m.txid = v_tx AND m.made
        UNION
        SELECT up.src, g.grp FROM up JOIN authz_sync.groups g ON g.key = up.c),
      made AS (INSERT INTO authz_sync.keys SELECT DISTINCT k.principal_type, k.principal_id, up.c FROM up
               CROSS JOIN LATERAL (SELECT k.principal_type, k.principal_id FROM authz_sync.keys k WHERE k.key = up.src
                                   AND k.principal_type <> ALL (v_whole) OFFSET 0) k
               ON CONFLICT DO NOTHING RETURNING key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM made z;
    END IF;
    DELETE FROM authz_int.sync_moved m WHERE m.txid = v_tx;
    -- the principals who are somebody now: their keys, worked out whole
    IF cardinality(v_came) > 0 THEN
    WITH made AS (INSERT INTO authz_sync.keys SELECT 'user', f.o_id, f.o_key FROM authz_int."sync_keys:user"(ARRAY(
                    SELECT substr(c, 6) FROM unnest(v_came) c WHERE left(c, 5) = 'user:')) f
                  ON CONFLICT DO NOTHING RETURNING key)
    SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM made z;
    END IF;
  END IF;
  -- file's readers
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'file' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "app"."files" x UNION SELECT x."id"::text FROM authz_sync."file__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'file') ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'file') END;
  -- (a batch of objects at a time, which a comparison holds in memory; what is there compared first, by the key's
  -- index: only the rows that change are visited)
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
    WITH fresh AS MATERIALIZED (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:file"(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f),
    there AS MATERIALIZED (SELECT x."id" AS id, x.key FROM authz_sync."file__readers" x
                           WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS id)),
    stale AS (SELECT s.id, s.key FROM there s EXCEPT SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep),
    added AS (SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep EXCEPT SELECT s.id, s.key FROM there s),
    gone AS (DELETE FROM authz_sync."file__readers" x USING stale s WHERE x."id" = s.id AND x.key = s.key
             RETURNING 1),
    made AS (INSERT INTO authz_sync."file__readers" SELECT a.o_id, a.o_key FROM added a
             ORDER BY 1, 2 ON CONFLICT DO NOTHING RETURNING 1),
    gone_from AS (DELETE FROM authz_sync.expanded x WHERE x.object_type = 'file' AND x.object_id IN (SELECT unnest(v_part))
             AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_dep AND f.o_id::text = x.object_id AND f.o_key = x.key) RETURNING 1),
    made_from AS (INSERT INTO authz_sync.expanded SELECT 'file', f.o_id::text, f.o_key FROM fresh f WHERE f.o_dep ON CONFLICT DO NOTHING RETURNING 1)
    SELECT count(*) INTO v_n FROM (SELECT 1 FROM gone UNION ALL SELECT 1 FROM made UNION ALL SELECT 1 FROM gone_from
                                   UNION ALL SELECT 1 FROM made_from) z;
  END LOOP;
  -- folder's readers
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'folder' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "app"."folders" x UNION SELECT x."id"::text FROM authz_sync."folder__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'folder') ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'folder') END;
  -- (a batch of objects at a time, which a comparison holds in memory; what is there compared first, by the key's
  -- index: only the rows that change are visited)
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
    WITH fresh AS MATERIALIZED (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:folder"(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f),
    there AS MATERIALIZED (SELECT x."id" AS id, x.key FROM authz_sync."folder__readers" x
                           WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS id)),
    stale AS (SELECT s.id, s.key FROM there s EXCEPT SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep),
    added AS (SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep EXCEPT SELECT s.id, s.key FROM there s),
    gone AS (DELETE FROM authz_sync."folder__readers" x USING stale s WHERE x."id" = s.id AND x.key = s.key
             RETURNING 1),
    made AS (INSERT INTO authz_sync."folder__readers" SELECT a.o_id, a.o_key FROM added a
             ORDER BY 1, 2 ON CONFLICT DO NOTHING RETURNING 1),
    gone_from AS (DELETE FROM authz_sync.expanded x WHERE x.object_type = 'folder' AND x.object_id IN (SELECT unnest(v_part))
             AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_dep AND f.o_id::text = x.object_id AND f.o_key = x.key) RETURNING 1),
    made_from AS (INSERT INTO authz_sync.expanded SELECT 'folder', f.o_id::text, f.o_key FROM fresh f WHERE f.o_dep ON CONFLICT DO NOTHING RETURNING 1)
    SELECT count(*) INTO v_n FROM (SELECT 1 FROM gone UNION ALL SELECT 1 FROM made UNION ALL SELECT 1 FROM gone_from
                                   UNION ALL SELECT 1 FROM made_from) z;
  END LOOP;
  -- note's readers
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'note' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "app"."notes" x UNION SELECT x."id"::text FROM authz_sync."note__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'note') ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'note') END;
  -- (a batch of objects at a time, which a comparison holds in memory; what is there compared first, by the key's
  -- index: only the rows that change are visited)
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
    WITH fresh AS MATERIALIZED (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:note"(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) f),
    there AS MATERIALIZED (SELECT x."id" AS id, x.key FROM authz_sync."note__readers" x
                           WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::integer FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'integer'))) AS id)),
    stale AS (SELECT s.id, s.key FROM there s EXCEPT SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep),
    added AS (SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep EXCEPT SELECT s.id, s.key FROM there s),
    gone AS (DELETE FROM authz_sync."note__readers" x USING stale s WHERE x."id" = s.id AND x.key = s.key
             RETURNING 1),
    made AS (INSERT INTO authz_sync."note__readers" SELECT a.o_id, a.o_key FROM added a
             ORDER BY 1, 2 ON CONFLICT DO NOTHING RETURNING 1),
    gone_from AS (DELETE FROM authz_sync.expanded x WHERE x.object_type = 'note' AND x.object_id IN (SELECT unnest(v_part))
             AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_dep AND f.o_id::text = x.object_id AND f.o_key = x.key) RETURNING 1),
    made_from AS (INSERT INTO authz_sync.expanded SELECT 'note', f.o_id::text, f.o_key FROM fresh f WHERE f.o_dep ON CONFLICT DO NOTHING RETURNING 1)
    SELECT count(*) INTO v_n FROM (SELECT 1 FROM gone UNION ALL SELECT 1 FROM made UNION ALL SELECT 1 FROM gone_from
                                   UNION ALL SELECT 1 FROM made_from) z;
  END LOOP;
  -- the next start or end of a share on what was worked out, after now(), when authz.sync_tick() works it out again
  -- (the work reads the shares as of the transaction's start: one that starts or ends while it is open, and a tick
  -- meanwhile, which can't see what it hasn't committed, are worked out again at the next tick)
  v_ids := ARRAY(SELECT DISTINCT x.type FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id = '*');
  WITH w AS MATERIALIZED (SELECT x.type, x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id <> '*'
                          AND x.type <> ALL (v_ids)),
  fresh AS MATERIALIZED (
    SELECT w.type, w.id, b.at FROM w
    CROSS JOIN LATERAL (SELECT min(v.at) AS at FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
                        WHERE g.object_type = w.type AND g.object_id = w.id AND v.at > now()) b
    WHERE b.at IS NOT NULL
    UNION ALL
    SELECT g.object_type, g.object_id, min(v.at) FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
    WHERE g.object_type = ANY (v_ids) AND v.at > now() GROUP BY g.object_type, g.object_id),
  gone AS (DELETE FROM authz_sync.due d USING w WHERE d.object_type = w.type AND d.object_id = w.id
           AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.type = d.object_type AND f.id = d.object_id) RETURNING 1),
  gone_all AS (DELETE FROM authz_sync.due d WHERE d.object_type = ANY (v_ids)
           AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.type = d.object_type AND f.id = d.object_id) RETURNING 1)
  INSERT INTO authz_sync.due SELECT f.type, f.id, f.at FROM fresh f
  ON CONFLICT (object_type, object_id) DO UPDATE SET at = EXCLUDED.at WHERE authz_sync.due.at <> EXCLUDED.at;
  DELETE FROM authz_int.sync_todo x WHERE x.txid = v_tx;
END $f$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."files"', '"app"."folders"', '"app"."notes"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

-- The sync role reads the index, and nothing else rowstile keeps
DO $sr$
DECLARE v_sync oid := to_regrole('"conf_electric"'); v_app oid := to_regrole('"conf_app"'); v_cols text;
BEGIN
  IF v_sync IS NULL THEN
    RAISE EXCEPTION 'the sync role conf_electric does not exist [AZ808]'
      USING HINT = 'make it for the engine: CREATE ROLE conf_electric LOGIN REPLICATION BYPASSRLS, then apply again';
  END IF;
  IF (SELECT r.rolsuper FROM pg_catalog.pg_roles r WHERE r.oid = v_sync) THEN
    RAISE EXCEPTION 'the sync role conf_electric is a superuser, which may turn row-level security off and change the rules [AZ808]'
      USING HINT = 'the engine connects as a role of its own: CREATE ROLE sync_engine LOGIN REPLICATION BYPASSRLS';
  END IF;
  IF pg_catalog.pg_has_role(v_sync, CURRENT_USER, 'MEMBER') THEN
    RAISE EXCEPTION 'the sync role conf_electric is the role that applies the policy (%), or a member of it [AZ808]', CURRENT_USER
      USING HINT = 'the engine connects as a role of its own, which owns nothing of the database';
  END IF;
  IF v_app IS NOT NULL AND (pg_catalog.pg_has_role(v_sync, v_app, 'MEMBER') OR pg_catalog.pg_has_role(v_app, v_sync, 'MEMBER')) THEN
    RAISE EXCEPTION 'the sync role conf_electric and the app role conf_app are one another''s members: the app would read every row [AZ808]'
      USING HINT = 'the engine connects as a role of its own, which the app role is not a member of, nor it of the app role';
  END IF;
  SELECT pg_catalog.string_agg(m.tbl || '.' || m.col, ', ' ORDER BY m.tbl, m.col) INTO v_cols FROM authz_int.masked_columns m
  WHERE pg_catalog.has_column_privilege(v_sync, m.tbl, m.col, 'SELECT');
  IF v_cols IS NOT NULL THEN
    RAISE EXCEPTION 'the sync role conf_electric may read masked columns: % [AZ809]', v_cols
      USING HINT = 'it reads every row, so a masked column would reach every client: revoke SELECT on the table, grant the other columns (GRANT SELECT (id, name) ON ...), then apply again';
  END IF;
END $sr$;
GRANT USAGE ON SCHEMA authz_sync TO "conf_electric";
GRANT SELECT ON ALL TABLES IN SCHEMA authz_sync TO "conf_electric";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."file__view"', 'authz_int."file__viewer"', 'authz_int."folder__edit"', 'authz_int."folder__edit__direct"', 'authz_int."folder__team"', 'authz_int."folder__view"', 'authz_int."folder__viewer"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"conf_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"conf_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.files:column owner_id:items"', '"app.files:column owner_id:why"', '"app.files:insert:items"', '"app.files:insert:refuse"', '"app.files:insert:why"', '"app.files:rules:explain"', '"app.files:update:items"', '"app.files:update:refuse"', '"app.files:update:why"', '"app.folders:column parent_id after:items"', '"app.folders:column parent_id after:why"', '"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.notes:rules:explain"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"conf_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.scim(text, text, text, text, text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, integer, text)', 'authz.explain(text, integer, text, text)', 'authz.list_shares(text, integer)', 'authz.list_links(text, integer)', 'authz.revoke_link(text, integer, text)', 'authz.create_link(text, integer, text, timestamptz)', 'authz.create_role(text, integer, text, text, text[])', 'authz.roles_of(text, integer)', 'authz.request_access(text, integer, text, text, interval)', 'authz.break_glass(text, integer, text, text, interval)', 'authz.start_review(text, integer, timestamptz)', 'authz.can(text, integer, text)', 'authz.who_among(text, integer, text, text[], text)', 'authz.perms(text, integer)', 'authz.share(text, text, text, text, integer, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, integer, text)', 'authz.share(text, integer, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, integer, text, text, text, text)', 'authz.share(text, integer, text, text, integer, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, integer, text, text, integer, text)']::regprocedure[]))
UNION ALL
SELECT n.nspname::text, gw.who, a.privilege_type,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who)
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname = 'authz_sync' AND a.grantee <> n.nspowner
    AND NOT coalesce(a.grantee = to_regrole('"conf_electric"') AND a.privilege_type = 'USAGE', false)
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON TABLE %s FROM %s CASCADE', a.privilege_type, c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND a.grantee <> c.relowner
    AND NOT coalesce(a.grantee = to_regrole('"conf_electric"') AND a.privilege_type = 'SELECT', false)
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND att.attacl IS NOT NULL LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO "conf_app";

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

-- Tables never analyzed (made just now, or too small for autovacuum to have reached them) are planned
-- as ten pages of rows: a table of 6 rows as thousands. Through the rules' lookups that becomes an estimate of
-- hundreds of thousands, and Postgres compiles (JIT) and plans for reads of a few rows. ANALYZE reads a
-- sample (30,000 rows at most) and blocks neither reads nor writes.
DO $an$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind = 'r' AND c.relpersistence <> 't' AND c.reltuples < 0
             AND pg_has_role(c.relowner, 'USAGE')
             AND (c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_int', 'authz_sync'))
                  OR c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."users"', '"app"."teams"', '"app"."team_members"', '"app"."folders"', '"app"."folder_teams"', '"app"."files"', '"app"."notes"']::text[]) x)) LOOP
    EXECUTE format('ANALYZE %s', r.tbl);
  END LOOP;
END $an$;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- The Electric suite's policy: folders inside folders, given to teams (and the teams inside them), files in
-- folders, shares on both, a confidential flag that keeps a file from those who read it only through its folder,
-- and notes on files whose body only their editors read. Electric syncs the files, the folders and the notes;
-- the sync index keeps who may read each row (sync lines), and the app's proxy sets each shape's filter.

app role conf_app
sync role conf_electric

type user = app.users(id integer)

type team = app.teams(id integer)
  member : user        = app.team_members(team_id -> user_id)
  member : team#member = app.teams(parent_id -> id)  -- the members of the teams inside it

type folder = app.folders(id integer)
  parent : folder      = parent_id
  owner  : user        = owner_id
  team   : team#member = app.folder_teams(folder_id -> team_id)
  viewer : user shared by edit

  can edit = owner or parent.edit
  can view = edit or team or viewer or parent.view

type file = app.files(id integer)
  folder : folder = folder_id
  owner  : user   = owner_id
  viewer : user shared by edit

  can edit = owner or folder.edit
  can view = edit or viewer or (folder.view and not {confidential})

type note = app.notes(id integer)
  file   : file = file_id
  author : user = author_id

  can edit = author or file.edit
  can view = file.view

rules app.folders
  select                 : view
  update                 : edit
  update parent_id after : parent.edit

rules app.files
  select          : view
  insert          : folder.edit and owner
  update          : edit
  update owner_id : nobody

rules app.notes view app.notes_visible
  select    : view
  mask body : edit

sync app.files : view
sync app.folders
sync app.notes
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+35dd949b5f8c', '3823b78b0065f497');

-- the session made read-only above (its statements committed one by one) is as it was again
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_migration.read_only', true) <> '' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', pg_catalog.current_setting('authz_migration.read_only'), false);
    PERFORM pg_catalog.set_config('authz_migration.read_only', '', false);
  END IF;
END $authz_tx$;
